INSERT INTO `weeks` (`n`, `start_date`, `end_date`, `dates_label`, `title`, `phase_code`, `focus`, `dsa_target`, `dsa_cumulative`, `gate_no`) VALUES
  (1, '2026-08-31', '2026-09-06', '31 Aug – 6 Sep 2026', 'The language, properly, and git you can actually use', 'A', 'JavaScript objects, data types and functions. Git beyond add-commit-push.', 24, 24, NULL),
  (2, '2026-09-07', '2026-09-13', '7–13 September 2026', 'HTML, CSS and the machine underneath', 'A', 'Layout by hand with no framework. Then close the Linux and networking gaps behind the VPS you already run.', 24, 48, NULL),
  (3, '2026-09-14', '2026-09-20', '14–20 September 2026', 'Prototypes, classes, errors and HTTP properly', 'A', 'The rest of the language, then the wire protocol every job interview assumes you understand.', 24, 72, NULL),
  (4, '2026-09-21', '2026-09-27', '21–27 September 2026', 'Async JavaScript. The week that decides everything after it', 'A', 'Promises, async/await, the event loop, microtasks. Two full days on chapter 11.', 24, 96, NULL),
  (5, '2026-09-28', '2026-10-04', '28 Sep – 4 Oct 2026', 'React fundamentals, and Gate 1', 'B', 'Components, state, effects, the rules of hooks. Then ship Project 1 to a public URL.', 22, 118, 1),
  (6, '2026-10-05', '2026-10-11', '5–11 October 2026', 'React deeper, and Tailwind v4', 'B', 'Custom hooks, context, composition, and CSS-first Tailwind.', 22, 140, NULL),
  (7, '2026-10-12', '2026-10-18', '12–18 October 2026', 'TypeScript from zero to strict', 'B', 'The handbook, then convert Project 1 end to end with no escape hatches.', 22, 162, NULL),
  (8, '2026-10-19', '2026-10-25', '19–25 October 2026', 'Node 24 and Express. API design that survives contact', 'C', 'REST done properly, middleware, validation at every boundary.', 22, 184, NULL),
  (9, '2026-10-26', '2026-11-01', '26 Oct – 1 Nov 2026', 'PostgreSQL 18. Schema, indexes, transactions', 'C', 'Design the schema on paper before you type it. Then earn every index.', 20, 204, NULL),
  (10, '2026-11-02', '2026-11-08', '2–8 November 2026', 'Next.js 16. Server components and the caching model', 'C', 'What runs on the server, what ships to the browser, and what is cached where.', 20, 224, NULL),
  (11, '2026-11-09', '2026-11-15', '9–15 November 2026', 'Auth you wrote yourself, and Gate 2', 'C', 'Sessions, password storage, and one real-time feature. No auth library.', 20, 244, 2),
  (12, '2026-11-16', '2026-11-22', '16–22 November 2026', 'Testing and CI that actually run', 'D', 'Twelve good tests, a real database in a container, and a merge gate that blocks red.', 20, 264, NULL),
  (13, '2026-11-23', '2026-11-29', '23–29 November 2026', 'Security. The 2025 list, not the 2021 one', 'D', 'OWASP Top 10:2025, eighth edition, applied to your own application.', 18, 282, NULL),
  (14, '2026-11-30', '2026-12-06', '30 Nov – 6 Dec 2026', 'Docker, Compose, Redis, and your own box', 'D', 'Hand it to somebody else and have it run. Then cache, session and rate-limit properly.', 18, 300, NULL),
  (15, '2026-12-07', '2026-12-13', '7–13 December 2026', 'Queues, system design, performance, observability. Gate 3', 'D', 'Backpressure, one architecture diagram, one before-and-after number, and logs you can search.', 18, 318, 3),
  (16, '2026-12-14', '2026-12-20', '14–20 December 2026', 'LLM plumbing for builders', 'E', 'AI SDK 7. Streaming, tool calls, structured output, and what actually costs money.', 18, 336, NULL),
  (17, '2026-12-21', '2026-12-27', '21–27 December 2026', 'RAG properly. Hybrid retrieval with citations', 'E', 'Chunk, contextualise, embed and BM25, hybrid retrieve, rerank, cite. No naive vector search.', 16, 352, NULL),
  (18, '2026-12-28', '2027-01-03', '28 Dec 2026 – 3 Jan 2027', 'Evaluation and LLM security', 'E', 'Ragas numbers in the README, and an honest failure-mode section.', 16, 368, NULL),
  (19, '2027-01-04', '2027-01-10', '4–10 January 2027', 'Agents and one MCP server', 'E', 'Write the loop by hand first. Then the server. Then, and only then, look at a framework.', 16, 384, NULL),
  (20, '2027-01-11', '2027-01-17', '11–17 January 2027', 'Mocks, revision, and the resume', 'F', 'No new topics. No new problems. Speaking while coding is a separate skill and this is the week it gets practised.', 16, 400, NULL),
  (21, '2027-01-18', '2027-01-24', '18–24 January 2027', 'Applications at volume. Gate 4', 'F', 'Not ten applications. A hundred. Volume first, funnel optimisation second.', 15, 415, 4)
