  ('2026-08-29', NULL, 'Saturday', 'launch', 0, 'Move local PostgreSQL 16 to 18. Verify pg_dump and restore both directions. Install the three Anki decks', 'log.md, versions.md, failed-twice.md, leads.csv and money.md created and committed', '30 more leads. Start sample site 1 for the worst site on the list'),
  ('2026-08-30', NULL, 'Sunday', 'launch', 6, 'Striver A2Z account and tracker. First 6 problems to prove the morning block works', 'Read Part 1 and Part 4 in full. Decide nothing else after this point', 'Finish both sample sites, put them live, paste the two links into the outreach scripts'),
  ('2026-08-31', 1, 'Monday', 'study', 4, 'javascript.info ch 4 (Objects). Type every example.', 'Repo scaffold + .gitignore + README skeleton', '15 first touches from the week list of 60. Log every touch'),
  ('2026-09-01', 1, 'Tuesday', 'study', 4, 'javascript.info ch 5 (Data types) parts 1–7.', 'Utility: core function, first five commits', '15 first touches, plus follow up 1 to Monday\'s list'),
  ('2026-09-02', 1, 'Wednesday', 'study', 4, 'javascript.info ch 5 parts 8–13 + Missing Semester shell lecture.', 'CUT POINT. Trim scope now if behind', '10 first touches, hold 2 calls, send every pending quote'),
