  ('2026-09-20', 3, 'Sunday', 'sunday_working', 0, 'SUNDAY, Working, 6 h. Python 2: files, JSON, requests, environments with uv', 'No BUILD block on Sunday', '30 minutes only: invoices, payments, pipeline hygiene'),
  ('2026-09-21', 4, 'Monday', 'study', 4, 'javascript.info ch 11 parts 1–4. Callbacks to promise chaining.', 'P1: async CSV ingest', '15 first touches from the week list of 60. Log every touch'),
  ('2026-09-22', 4, 'Tuesday', 'study', 4, 'javascript.info ch 11 parts 5–8. Promise API, microtasks, async/await.', 'P1: streaming parse for large files', '15 first touches, plus follow up 1 to Monday\'s list'),
  ('2026-09-23', 4, 'Wednesday', 'study', 4, 'latentflip.com/loupe + jsv9000.app. Draw the loop from memory.', 'CUT POINT. P1: progress reporting', '10 first touches, hold 2 calls, send every pending quote'),
  ('2026-09-24', 4, 'Thursday', 'study', 4, 'Write retry-with-backoff, a timeout, and a concurrency limiter by hand.', 'P1: wire the retry into ingest', 'Delivery only. The current paid job, one progress line to the client'),
